import React, { useState, useEffect } from 'react';
import { apiGetCampaignDetails, apiGetCollaborations, apiUpdateCollaborationStatus, apiUpdateDeliverables, apiUpdatePaymentDetails, getCurrentUser } from '../services/api';

interface CampaignDetailsProps {
  campaignId: string;
  onBack: () => void;
}

const CampaignDetails: React.FC<CampaignDetailsProps> = ({ campaignId, onBack }) => {
  const currentUser = getCurrentUser();
  const isBrand = currentUser?.userType === 'Brand';

  const [campaign, setCampaign] = useState<any>(null);
  const [collaborations, setCollaborations] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDetails();
  }, [campaignId]);

  const fetchDetails = async () => {
    try {
      const camp = await apiGetCampaignDetails(campaignId);
      setCampaign(camp);

      const allCollabs = await apiGetCollaborations();
      const relatedCollabs = allCollabs.filter((c: any) => c.campaignId?._id === campaignId);
      setCollaborations(relatedCollabs);
    } catch (err) {
      console.error('Failed to load campaign details');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (collabId: string, newStatus: string) => {
    try {
      await apiUpdateCollaborationStatus(collabId, newStatus);
      fetchDetails();
    } catch (err) {
      alert('Failed to update status');
    }
  };

  const handleUpdatePayment = async (collabId: string, status: string) => {
    try {
      await apiUpdatePaymentDetails(collabId, { status });
      fetchDetails();
    } catch (err) {
      alert('Failed to update payment');
    }
  };

  const handeAddDeliverable = async (collabId: string, currentDeliverables: any[], type: string) => {
    try {
      const updated = [...currentDeliverables, { type, status: 'Pending', link: '' }];
      await apiUpdateDeliverables(collabId, updated);
      fetchDetails();
    } catch (err) {
      alert('Failed to add deliverable');
    }
  };

  const handleUpdateDeliverableStatus = async (collabId: string, currentDeliverables: any[], index: number, newStatus: string) => {
    try {
      const updated = [...currentDeliverables];
      updated[index].status = newStatus;
      await apiUpdateDeliverables(collabId, updated);
      fetchDetails();
    } catch (err) {
      alert('Failed to update deliverable');
    }
  };

  if (loading) return <div className="p-8 text-white">Loading...</div>;
  if (!campaign) return <div className="p-8 text-white">Campaign not found</div>;

  return (
    <div className="flex flex-col h-full bg-base-bg text-base-text transition-colors duration-300">
      <header className="flex items-center justify-between p-4 border-b border-white/10 shrink-0">
        <button onClick={onBack} className="text-brand-magenta font-semibold"> Back </button>
        <h1 className="text-xl font-bold">{campaign.title}</h1>
        <div className="w-12" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-8">
        <section className="bg-white/5 p-6 rounded-2xl border border-white/10">
          <h2 className="text-lg font-bold mb-4 text-brand-cyan">Campaign Brief</h2>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-xs text-white/50 uppercase">Goal</p>
              <p className="font-semibold">{campaign.goal}</p>
            </div>
            <div>
              <p className="text-xs text-white/50 uppercase">Budget</p>
              <p className="font-semibold">${campaign.budget}</p>
            </div>
            <div>
              <p className="text-xs text-white/50 uppercase">Niche</p>
              <p className="font-semibold">{campaign.niche || 'N/A'}</p>
            </div>
          </div>
        </section>

        <section>
          <h2 className="text-xl font-bold mb-4">Collaborations</h2>
          {collaborations.length === 0 ? (
            <p className="text-white/50">No influencers have been invited yet.</p>
          ) : (
            <div className="space-y-6">
              {collaborations.map(collab => (
                <div key={collab._id} className="bg-white/5 p-6 rounded-2xl border border-white/10 space-y-4">
                  <div className="flex justify-between items-center border-b border-white/10 pb-4">
                    <div>
                      <h3 className="font-bold text-lg">Partner: {isBrand ? collab.influencerId?.displayName : collab.brandId?.displayName}</h3>
                      <p className="text-sm text-white/70">Status: <span className="text-white font-semibold">{collab.status}</span></p>
                    </div>
                    <div className="flex gap-2 text-sm">
                      {isBrand && collab.status !== 'Completed' && (
                         <button onClick={() => handleUpdateStatus(collab._id, 'Completed')} className="px-3 py-1 bg-brand-cyan text-black rounded hover:bg-brand-cyan/80">Mark Completed</button>
                      )}
                      {!isBrand && collab.status === 'Invited' && (
                         <button onClick={() => handleUpdateStatus(collab._id, 'Negotiating')} className="px-3 py-1 bg-brand-magenta text-white rounded hover:bg-brand-magenta/80">Accept Invite</button>
                      )}
                    </div>
                  </div>

                  {/* Deliverables */}
                  <div>
                    <div className="flex justify-between items-center mb-2">
                       <h4 className="font-bold text-white/80">Deliverables Tracker</h4>
                       {isBrand && (
                         <button onClick={() => handeAddDeliverable(collab._id, collab.deliverables || [], 'Post')} className="text-xs text-brand-cyan">Add +</button>
                       )}
                    </div>
                    {(collab.deliverables || []).length === 0 ? (
                      <p className="text-sm text-white/50">No specific deliverables set.</p>
                    ) : (
                      <ul className="space-y-2">
                        {collab.deliverables.map((del: any, idx: number) => (
                          <li key={idx} className="flex justify-between items-center bg-black/20 p-3 rounded-lg text-sm">
                            <span>{del.type}</span>
                            <div className="flex items-center gap-3">
                              <span className={`px-2 py-0.5 rounded-full text-xs ${del.status === 'Approved' ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'}`}>{del.status}</span>
                              {isBrand && del.status === 'Submitted' && (
                                <button onClick={() => handleUpdateDeliverableStatus(collab._id, collab.deliverables, idx, 'Approved')} className="text-xs bg-white/10 px-2 py-1 rounded">Approve</button>
                              )}
                              {!isBrand && del.status === 'Pending' && (
                                <button onClick={() => handleUpdateDeliverableStatus(collab._id, collab.deliverables, idx, 'Submitted')} className="text-xs bg-white/10 px-2 py-1 rounded">Submit</button>
                              )}
                            </div>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>

                  {/* Payment */}
                  <div className="pt-4 border-t border-white/10">
                    <h4 className="font-bold text-white/80 mb-2">Payment Status</h4>
                    <div className="flex justify-between items-center">
                      <p className="text-sm">Amount: <span className="font-bold text-brand-cyan">${collab.paymentDetails?.amount || 0}</span></p>
                      <div className="flex items-center gap-3 text-sm">
                        <span className={`px-2 py-0.5 rounded-full text-xs ${collab.paymentDetails?.status === 'Paid' ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
                          {collab.paymentDetails?.status || 'Pending'}
                        </span>
                        {isBrand && collab.paymentDetails?.status !== 'Paid' && (
                          <button onClick={() => handleUpdatePayment(collab._id, 'Paid')} className="text-xs bg-brand-cyan/20 text-brand-cyan px-2 py-1 rounded hover:bg-brand-cyan/40">Mark as Paid</button>
                        )}
                      </div>
                    </div>
                  </div>

                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

export default CampaignDetails;
